<script setup lang="ts">
import {ref,computed,onUnmounted} from 'vue';import {onHide} from '@dcloudio/uni-app';import PageShell from '../../components/PageShell.vue';import OrderCard from '../../components/OrderCard.vue';import EmptyState from '../../components/EmptyState.vue';import {usePage} from '../../composables/usePage';import {usePagination} from '../../composables/usePagination';import {request} from '../../utils/request';import {go,status,time,confirm} from '../../utils/format';const filter=ref(''),profile=ref<any>(null),now=ref(Date.now());let ticker:ReturnType<typeof setInterval>|undefined;function stop(){if(ticker)clearInterval(ticker)}onHide(stop);onUnmounted(stop);const pager=usePagination(p=>request('/orders?page='+p+'&status='+filter.value));const {loading,error,load,busy,action}=usePage(async()=>{profile.value=await request('/sitter/profile');await pager.load(true);stop();ticker=setInterval(()=>now.value=Date.now(),1000)});const pending=computed(()=>pager.rows.value.filter(o=>o.status==='PENDING_ACCEPT'));const seconds=(o:any)=>Math.max(0,Math.ceil((Date.parse(o.accept_deadline)-now.value)/1000));async function respond(id:number,accept:boolean){if(!accept&&!await confirm('确认拒绝本次派单？订单会退回平台重新调度。'))return;await request('/orders/'+id+'/'+(accept?'accept':'reject'),'POST');await load()}
</script><template><PageShell title="喂养师工作台" active="home" :loading="loading" :error="error" @retry="load"><view class="row" style="margin-bottom:20px"><view><view class="title">今天，也要用心照顾。</view><text class="subtitle">{{profile?.name}} · {{profile?.grade_code}}</text></view><text class="pill green">{{status(profile?.status)}}</text></view><view v-if="profile?.status!=='ACTIVE'" class="notice warning">当前档案尚不可接单。请在「我的」查看资质与审核状态。</view><view v-for="o in pending" :key="o.id" class="dark-card"><view class="row"><text>✦ 新派单</text><text class="pill">{{seconds(o)}} 秒内响应</text></view><view style="font-size:19px;margin:16px 0">{{o.pet_snapshot?.map((p:any)=>p.name).join('、')}} · 上门喂养</view><text class="muted">{{time(o.service_start)}} · {{o.address_snapshot?.district}}</text><view class="inline-actions"><button class="outline" :disabled="busy||!seconds(o)" @click="action(()=>respond(o.id,false),'')">拒绝</button><button class="primary" :disabled="busy||!seconds(o)" @click="action(()=>respond(o.id,true),'接单成功')">确认接单</button></view></view><view class="section">我的任务 <text class="link" @click="load">刷新</text></view><view class="tabs"><view v-for="t in [['','全部'],['ACCEPTED','待上门'],['SERVICING','服务中'],['COMPLETED','已完成']]" :key="t[0]" :class="['tab',{active:filter===t[0]}]" @click="filter=t[0];load()">{{t[1]}}</view></view><OrderCard v-for="o in pager.rows.value" :key="o.id" :order="o" sitter/><EmptyState v-if="!loading&&!pager.rows.value.length" text="暂无任务，新的派单会在这里出现"/><button v-if="pager.rows.value.length<pager.total.value" class="outline" @click="action(()=>pager.load(),'')">加载更多</button><view class="footer-note" @click="go('sitter/schedule')">查看本周档期 ›</view></PageShell></template>
